import fitz, os, re
from collections import defaultdict

EMAIL_RE = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")
ARXIV_RE = re.compile(r"arXiv:\d{4}\.\d{5}(?:v\d+)?")
DOI_RE = re.compile(r"10\.\d{4,9}/[^\s]+")

path = "/root/paper3.pdf"
output = "/root/redacted/paper3.pdf"

extra_patterns = [
    "Duke University, Durham, USA",
    "NSF 2112562",
    "ARO W911NF-23-2-",
]

# build patterns similar to before
LINE_CONTAINS = [
    "Yueqian Lin *",
    "Yiran Chen",
    "Equal contribution",
    "respondence to: Yueqian Lin",
    "ICML Workshop on Machine Learning for Audio",
    "Canada. Copyright 2025",
]

def find_references_page(doc):
    for i, page in enumerate(doc):
        if "references" in page.get_text().lower():
            return i
    return None


def build_patterns(path):
    doc = fitz.open(path)
    refs_page = find_references_page(doc)
    patterns = set(extra_patterns)
    lines = []
    for page_num, page in enumerate(doc):
        if refs_page is not None and page_num >= refs_page:
            break
        text = page.get_text()
        lines.extend(text.splitlines())
        for m in EMAIL_RE.findall(text):
            patterns.add(m)
        for m in ARXIV_RE.findall(text):
            patterns.add(m)
        for m in DOI_RE.findall(text):
            patterns.add(m)
    for needle in LINE_CONTAINS:
        for line in lines:
            if needle in line:
                patterns.add(line)
    doc.close()
    return sorted(p for p in patterns if p)


def verify_redaction(original_path, output_path):
    orig = fitz.open(original_path)
    redc = fitz.open(output_path)
    orig_len = sum(len(p.get_text()) for p in orig)
    redc_len = sum(len(p.get_text()) for p in redc)
    print(f"Original: {len(orig)} pages, {orig_len} chars")
    print(f"Redacted: {len(redc)} pages, {redc_len} chars")
    print(f"Retained: {redc_len/orig_len:.1%}")
    if len(redc) != len(orig):
        raise ValueError(f"Page count changed: {len(orig)} -> {len(redc)}")
    if redc_len < 1000:
        raise ValueError(f"PDF corrupted: only {redc_len} chars remain!")
    if redc_len < orig_len * 0.7:
        raise ValueError(f"Too much removed: kept only {redc_len/orig_len:.0%}")
    orig.close(); redc.close()
    print("✓ Verification passed")


def redact_with_pymupdf(input_path: str, output_path: str, patterns: list[str]):
    doc = fitz.open(input_path)
    refs_page = find_references_page(doc)
    match_counts = defaultdict(int)
    for page_num, page in enumerate(doc):
        if refs_page is not None and page_num >= refs_page:
            continue
        for pattern in patterns:
            rects = page.search_for(pattern)
            if rects:
                match_counts[pattern] += len(rects)
            for rect in rects:
                page.add_redact_annot(rect, fill=(0,0,0))
        page.apply_redactions()
    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    doc.save(output_path)
    doc.close()
    print(f"\n{input_path} -> {output_path}")
    print(f"Patterns: {len(patterns)}; matched: {sum(match_counts.values())}")
    missing = [p for p in patterns if match_counts.get(p, 0) == 0]
    if missing:
        print("Unmatched patterns:")
        for p in missing:
            print("-", p)
    verify_redaction(input_path, output_path)

patterns = build_patterns(path)
redact_with_pymupdf(path, output, patterns)
